{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL-hermes-luna6-medium-fresh0/frozen/held-out-reference/play/users/u048/system/state/workspace/programs/task-31d198b0.py",
 "content": "def transform(grid):
    """Stamp the sole patterned rectangular frame into other framed shapes."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    boxes = {}
    for color in {v for row in grid for v in row if v}:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if (all(grid[r0][c] == color for c in range(c0, c1 + 1)) and
            all(grid[r1][c] == color for c in range(c0, c1 + 1)) and
            all(grid[r][c0] == color for r in range(r0, r1 + 1)) and
            all(grid[r][c1] == color for r in range(r0, r1 + 1))):
            pat = [[grid[r][c] == color for c in range(c0 + 1, c1)]
                   for r in range(r0 + 1, r1)]
            boxes[color] = (r0, r1, c0, c1, pat)

    sources = [color for color, (_, _, _, _, pat) in boxes.items()
               if any(any(row) for row in pat)]
    if len(sources) != 1:
        return out
    source = sources[0]
    sr0, sr1, sc0, sc1, pattern = boxes[source]
    sh, sw = sr1 - sr0 - 1, sc1 - sc0 - 1
    for color, (r0, r1, c0, c1, _) in boxes.items():
        if color == source:
            continue
        # Apply the same pattern within frame footprints that match the source
        # size or are one cell shorter in height (the demonstrated clipped case).
        th, tw = r1 - r0 - 1, c1 - c0 - 1
        if tw == sw and th in (sh, sh - 1):
            for r in range(r0 + 1, r1):
                for c in range(c0 + 1, c1):
                    out[r][c] = color if pattern[r - r0 - 1][c - c0 - 1] else 0
        elif th <= sh and tw <= sw:
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    out[r][c] = 0
    return out
