 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    boxes = {}
    for color in {v for row in grid for v in row if v}:
        pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0,r1 = min(r for r,c in pts), max(r for r,c in pts)
        c0,c1 = min(c for r,c in pts), max(c for r,c in pts)
        if (all(grid[r0][c] == color for c in range(c0,c1+1)) and
            all(grid[r1][c] == color for c in range(c0,c1+1)) and
            all(grid[r][c0] == color for r in range(r0,r1+1)) and
            all(grid[r][c1] == color for r in range(r0,r1+1))):
            pat = [[grid[r][c] == color for c in range(c0+1,c1)] for r in range(r0+1,r1)]
            boxes[color] = (r0,r1,c0,c1,pat)
    sources = [col for col,(_,_,_,_,p) in boxes.items() if any(any(row) for row in p)]
    if len(sources) != 1:
        return out
    source = sources[0]
    sr0,sr1,sc0,sc1,pattern = boxes[source]
    sh, sw = sr1-sr0-1, sc1-sc0-1
    for color,(r0,r1,c0,c1,_) in boxes.items():
        if color == source:
            continue
        # The stamp fills frames of its exact interior footprint. Smaller
        # frames are distractors and disappear; larger frames remain untouched.
        th,tw = r1-r0-1,c1-c0-1
        if (th,tw) == (sh,sw):
            for r in range(r0+1,r1):
                for c in range(c0+1,c1):
                    out[r][c] = color if pattern[r-r0-1][c-c0-1] else 0
        elif th < sh and tw < sw:
            for r in range(r0,r1+1):
                for c in range(c0,c1+1):
                    out[r][c] = 0
    return out
